// ============================================================
//  PAPER LIBRARY
//  Generated by `node papers-src/build.mjs` → src/data/library.json.
//  To add a paper, add a doc in papers-src/docs (see papers-src/GUIDE.md)
//  and run the build. Do not edit library.json by hand.
// ============================================================
import library from "./library.json";

export type Grade = 9 | 10 | 11;
export type Medium = "English" | "Sinhala";
export type Kind = "Model Paper" | "Marking Scheme" | "Worked Answers" | "Tutorial";

export interface Doc {
  id: string;
  title: string;
  grade: Grade;
  medium: Medium;
  kind: Kind;
  topic: string | null;
  number: number | null;
  pairOf: string | null;
  file: string;
}

/** A card on the website: a paper (or answer sheet) plus its marking scheme, if any. */
export interface Paper extends Doc {
  scheme?: Doc;
}

const DOCS = library as Doc[];

const schemeFor = new Map(DOCS.filter((d) => d.pairOf).map((d) => [d.pairOf!, d]));
const hasParent = new Set(DOCS.map((d) => d.id));

const order = (p: Doc) =>
  // grade desc, model papers first, then number / topic
  [-p.grade, p.kind === "Model Paper" ? 0 : p.kind === "Worked Answers" ? 1 : 2, p.number ?? 0, p.topic ?? "", p.medium];

/** Tutorial notes PDFs (shown on the Tutorials page, not in the paper library). */
export const TUTORIAL_DOCS: Doc[] = DOCS.filter((d) => d.kind === "Tutorial");

export const PAPERS: Paper[] = DOCS
  .filter((d) => d.kind !== "Tutorial")
  .filter((d) => !d.pairOf || !hasParent.has(d.pairOf)) // schemes attach to their paper
  .map((d) => ({ ...d, scheme: schemeFor.get(d.id) }))
  .sort((a, b) => {
    const x = order(a), y = order(b);
    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
    return 0;
  });
